type Step = fn(&mut Message) -> Result<(), StepError>;

fn advance(msg: &mut Message, slip: &[Step]) -> Result<(), StepError> {
    while msg.cursor < slip.len() {
        let step = slip[msg.cursor];      // copy the fn pointer out
        step(msg)?;                       // ? aborts, leaving partial effects
        msg.cursor += 1;
    }
    Ok(())
}
